EDITS = {'hermes_cli/web_routers/sessions.py': {'sha256': 'd934e94cb34151f4ec05f71511cd799f0b54daaa54d3ccde1aa86b28c1b66ae1', 'edits': [[699, 700, '    session_id: str, row_id: Optional[int] = Query(None, ge=1), profile: Optional[str] = None,\n'], [701, 701, '    before_cursor: Optional[int] = Query(None, ge=1), after_cursor: Optional[int] = Query(None, ge=1),\n'], [702, 703, '    """Bounded prompt jump or adjacent display page, including inside a long turn."""\n    if sum(value is not None for value in (row_id, before_cursor, after_cursor)) != 1:\n        raise HTTPException(status_code=422, detail="Provide exactly one of row_id, before_cursor, after_cursor")\n'], [709, 710, '        page = read_around(db, sid, row_id, limit=limit,\n                           before_cursor=before_cursor, after_cursor=after_cursor)\n']]}, 'hermes_state_timeline.py': {'sha256': 'ad605786c9ef97da056dbe88e2302d033207ac099cb6cc99b8efcaded38c7329', 'edits': [[100, 102, 'def get_session_messages_around(\n    db, session_id, row_id=None, *, limit=120, before_cursor=None, after_cursor=None,\n):\n    """Read one bounded display page, at a prompt or adjacent to a stable cursor.\n'], [103, 105, "    Cursors are display sort ids, not payload row ids or offsets into hydrated\n    bubbles. They survive protected-tail replacement during compaction. Only\n    the selected page's payloads cross the SQLite/Python boundary.\n"], [106, 106, '    if sum(value is not None for value in (row_id, before_cursor, after_cursor)) != 1:\n        raise ValueError("Provide exactly one of row_id, before_cursor, after_cursor")\n'], [108, 115, ''], [116, 129, '        params = {"sid": session_id, "limit": limit}\n        if row_id is not None:\n            # The existing jump contract remains prompt-only and owner-exact.\n            anchor = conn.execute(\n                "SELECT content, display_kind, _compressed_summary FROM messages "\n                "WHERE session_id = ? AND id = ? AND role = \'user\' AND (active = 1 OR compacted = 1)",\n                (session_id, row_id),\n            ).fetchone()\n            if anchor is None or not _prompt_preview(db, *anchor):\n                return None\n            selected = conn.execute(sql + "SELECT sort_id FROM display_rows WHERE row_id = :row_id",\n                                    {"sid": session_id, "row_id": row_id}).fetchone()\n            if selected is None:\n                return None\n            params["start"] = selected["sort_id"]\n            predicate, order = "sort_id >= :start", "ASC"\n        elif before_cursor is not None:\n            params["start"] = before_cursor\n            predicate, order = "sort_id < :start", "DESC"\n        else:\n            params["start"] = after_cursor\n            predicate, order = "sort_id > :start", "ASC"\n        # Predicate/order are fixed SQL fragments above, never request strings.\n        rows = conn.execute(sql + f"""\n            SELECT m.*, page.sort_id AS timeline_cursor\n            FROM (SELECT row_id, sort_id FROM display_rows\n                  WHERE {predicate} ORDER BY sort_id {order} LIMIT :limit) AS page\n'], [131, 131, '        # Offsets are informational only. Navigation uses the two boundary cursors.\n        params["first"] = rows[0]["timeline_cursor"] if rows else params["start"]\n        counts = conn.execute(sql + """\n            SELECT COUNT(*) AS total, COALESCE(SUM(sort_id < :first), 0) AS offset FROM display_rows\n        """, params).fetchone()\n        # A page can begin in the middle of a single long tool turn. Keep its\n        # rail identity even after the prompt\'s payload page is released.\n        leading = conn.execute(_display_rows_sql(conn, session_id, users_only=True) + """\n            SELECT row_id FROM display_rows JOIN messages m ON m.id = row_id\n            WHERE sort_id < :first\n              AND timeline_preview(m.content, m.display_kind, m._compressed_summary) <> \'\'\n            ORDER BY sort_id DESC LIMIT 1\n        """, params).fetchone() if rows else None\n'], [132, 132, '    offset = counts["offset"] if rows else (0 if before_cursor is not None else counts["total"])\n'], [134, 137, '        "offset": offset, "total": counts["total"],\n        "has_older": offset > 0,\n        "has_newer": offset + len(messages) < counts["total"],\n        "first_cursor": rows[0]["timeline_cursor"] if rows else None,\n        "last_cursor": rows[-1]["timeline_cursor"] if rows else None,\n        "leading_prompt_row_id": leading["row_id"] if leading else None,\n']]}, 'tests/hermes_cli/test_session_timeline.py': {'sha256': 'e9135c8f21096fe90daee6a2d6853702d500870a48f3ecd82768d9937ac6e52f', 'edits': [[214, 214, '\n\n@pytest.mark.parametrize("legacy", [False, True])\ndef test_adjacent_pages_cross_long_tool_turn_without_gaps_and_survive_compaction(timeline_store, legacy, monkeypatch):\n    db, client, _ = timeline_store\n    sid = "timeline-root"\n    rows = [{"role": "user", "content": "long turn", "timestamp": 1}]\n    for i in range(150):\n        rows.extend([\n            {"role": "assistant", "content": f"step {i}", "timestamp": i + 2,\n             "tool_calls": [{"id": f"call-{i}", "type": "function",\n                             "function": {"name": "terminal", "arguments": "{}"}}]},\n            {"role": "tool", "content": f"result {i}", "timestamp": i + 2,\n             "tool_name": "terminal", "tool_call_id": f"call-{i}"},\n        ])\n    rows.extend([{"role": "user", "content": "last ask", "timestamp": 999},\n                 {"role": "assistant", "content": "last answer", "timestamp": 1000}])\n    db.append_messages_batch(sid, rows)\n    original = db.get_messages(sid)\n    # Every request hydrates at most its bounded selected payloads.\n    hydrated = []\n    decode = SessionDB._row_to_message_dict\n    def counted(self, row, *args, **kwargs):\n        hydrated.append(row["id"])\n        return decode(self, row, *args, **kwargs)\n    monkeypatch.setattr(SessionDB, "_row_to_message_dict", counted)\n    if legacy:\n        db._write_sql("UPDATE messages SET display_identity = NULL, display_order = NULL WHERE session_id = ?", (sid,))\n    url = f"/api/sessions/{sid}/messages/around"\n    def read(**params):\n        hydrated.clear()\n        response = client.get(url, params=params)\n        assert response.status_code == 200, response.text\n        page = response.json()\n        assert len(hydrated) == len(page["messages"]) <= 120\n        return page\n    first = read(row_id=original[0]["id"])\n    # Replace the active tail while a client still holds the old logical cursor.\n    db.archive_and_compact(sid, original[100:])\n    if legacy:\n        db._write_sql("UPDATE messages SET display_identity = NULL, display_order = NULL WHERE session_id = ?", (sid,))\n    second = read(after_cursor=first["pagination"]["last_cursor"])\n    third = read(after_cursor=second["pagination"]["last_cursor"])\n    combined = first["messages"] + second["messages"] + third["messages"]\n    assert [m["content"] for m in combined] == [m["content"] for m in rows]\n    assert first["pagination"]["has_older"] is False\n    assert third["pagination"]["has_newer"] is False\n    assert second["pagination"]["leading_prompt_row_id"] == original[0]["id"]\n    backward = read(before_cursor=third["pagination"]["first_cursor"])\n    assert [m["content"] for m in backward["messages"]] == [m["content"] for m in second["messages"]]\n    backward = read(before_cursor=backward["pagination"]["first_cursor"])\n    assert [m["content"] for m in backward["messages"]] == [m["content"] for m in first["messages"]]\n    assert backward["pagination"]["has_older"] is False\n\n\n@pytest.mark.parametrize("params", [{}, {"row_id": 1, "after_cursor": 1},\n                                     {"before_cursor": 1, "after_cursor": 1},\n                                     {"before_cursor": 0}, {"after_cursor": 1, "limit": 121}])\ndef test_adjacent_page_addresses_are_exclusive_and_bounded(timeline_store, params):\n    _, client, _ = timeline_store\n    assert client.get("/api/sessions/timeline-root/messages/around", params=params).status_code == 422\n\n\ndef test_adjacent_page_keeps_exact_profile_ownership(timeline_store):\n    db, client, home = timeline_store\n    sid = "timeline-root"\n    db.append_messages_batch(sid, [{"role": "user", "content": "default ask"},\n                                   {"role": "assistant", "content": "default reply"}])\n    work = home / "profiles" / "work"\n    work.mkdir(parents=True)\n    with SessionDB(db_path=work / "state.db") as other:\n        other.create_session(session_id=sid, source="desktop")\n        other.append_messages_batch(sid, [{"role": "user", "content": "work ask"},\n                                          {"role": "assistant", "content": "work reply"}])\n    for profile in ("default", "work", "default"):\n        url = f"/api/sessions/{sid}/messages/around"\n        first = client.get(url, params={"profile": profile, "row_id": 1, "limit": 1}).json()\n        page = client.get(url, params={"profile": profile,\n                         "after_cursor": first["pagination"]["last_cursor"]}).json()\n        assert [m["content"] for m in page["messages"]] == [f"{profile} reply"]\n    db._write_sql("UPDATE sessions SET profile_name = \'wrong-owner\' WHERE id = ?", (sid,))\n    assert client.get(url, params={"after_cursor": 1}).status_code == 404\n    assert client.get("/api/sessions/timeline-ro/messages/around?after_cursor=1").status_code == 404\n']]}}
